Adding the origin configuration to the manifest.

Example:

`azion.config.js`

```js

export default {
  origin: [
    {
      name: "my origin storage",
      type: "object_storage",
      bucket: "mybucket",
      prefix: "myfolder",
    },
  ],
  rules: {
    request: [
      {
        match: "/^/_statics/;", // start with /_statics
        setOrigin: {
          name: "my origin storage",
          type: "object_storage",
        },
      }
    ],
  },
};

```

The manifest generated in: `./.edge/manifest.json`

```json
{
  "origin": [
    {
      "name": "my origin storage",
      "origin_type": "object_storage",
      "bucket": "mybucket",
      "prefix": "myfolder"
    }
  ],
  "cache": [],
  "rules": [
   ...
    {
      "criteria": [
        [
          {
            "variable": "${uri}",
            "operator": "matches",
            "conditional": "if",
            "input_value": "/^/_statics/;"
          }
        ]
      ],
      "behaviors": [
        {
          "name": "set_origin",
          "target": "my origin storage"
        }
      ]
    }
  ]
}
```

